    x, y = own_pos
    mode = observation.get('game_mode', 'unknown').lower()
    resources = observation.get('resources', [])
    opponents = observation.get('opponents', [])
    territories = observation.get('territories', [])

    def find_nearest(targets, current):
        min_dist = float('inf')
        target_pos = None
        for t in targets:
            tx, ty = t
            dist = abs(tx - current[0]) + abs(ty - current[1])
            if dist < min_dist:
                min_dist = dist
                target_pos = (tx, ty)
        return target_pos

    def move_towards(target):
        tx, ty = target
        dx = 0
        dy = 0
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1
        return [dx, dy]

    # For robustness, prefer staying still if movement isn't beneficial.
    def safe_move(target):
        dx, dy = move_towards(target)
        # Prevent moving outside some boundary (assuming 0 <= x,y <= 100)
        next_x = x + dx
        next_y = y + dy
        if next_x < 0 or next_x > 100 or next_y < 0 or next_y > 100:
            return [0, 0]
        return [dx, dy]

    if mode == 'resource_collection':
        target = find_nearest(resources, own_pos)
        if target:
            return safe_move(target)

    elif mode == 'pursuit_evasion':
        target = find_nearest(opponents, own_pos)
        if target:
            return safe_move(target)

    elif mode == 'territory_control':
        target = find_nearest(territories, own_pos)
        if target:
            return safe_move(target)

    # Default fallback: do not move
    return [0, 0]

